import java.util.ArrayList;
import java.util.Random;

/**
 * A catalogue of the books in one library. It can search the titles
 * and pick a book at random.
 * @author Pranjal Patra
 * @version 2.0
 */
public class Catalogue
{
    private ArrayList<Book> books;
    private Random generator;

    /**
     * Create an empty catalogue.
     */
    public Catalogue()
    {
        books = new ArrayList<>();
        generator = new Random(42);
    }

    /**
     * Add a book to the end of the catalogue.
     * @param book The book to add; must not be null.
     */
    public void addBook(Book book)
    {
        books.add(book);
    }

    /**
     * Return the number of books in the catalogue.
     * @return The number of books.
     */
    public int getCount()
    {
        return books.size();
    }

    /**
     * Print every book whose title contains the query. Case and the
     * spaces around the query do not matter.
     * @param query The text to search for; must not be null.
     */
    public void printMatches(String query)
    {
        String cleaned = query.trim().toLowerCase();
        if(cleaned.isEmpty()) {
            System.out.println("Please type a word to search for.");
            return;
        }
        boolean found = false;
        for(Book book : books) {
            if(book.getTitle().toLowerCase().contains(cleaned)) {
                System.out.println(book.getTitle() + " (" + book.getCallNumber() + ")");
                found = true;
            }
        }
        if(!found) {
            System.out.println("No titles match \"" + cleaned + "\".");
        }
    }

    /**
     * Choose one book at random. The book stays in the catalogue.
     * @return A book from the catalogue, or null if it is empty.
     */
    public Book pickRandom()
    {
        if(books.isEmpty()) {
            return null;
        }
        int index = generator.nextInt(books.size());
        return books.get(index);
    }
}

