import java.util.ArrayList;

public class ContactList
{
    private ArrayList<Contact> contacts;

    public ContactList()
    {
        contacts = new ArrayList<>();
    }

    public void addContact(String name, String email)
    {
        contacts.add(new Contact(name.trim(), email.trim().toLowerCase()));
    }

    public void printAll()
    {
        for(Contact contact : contacts) {
            System.out.println(contact.getInitials() + " " + contact.getName()
                + " <" + contact.getEmail() + ">");
        }
    }

    public void printSearch(String text)
    {
        String cleaned = text.trim().toLowerCase();
        boolean found = false;
        for(Contact contact : contacts) {
            if(contact.getName().toLowerCase().contains(cleaned)) {
                System.out.println(contact.getName());
                found = true;
            }
        }
        if(!found) {
            System.out.println("No contacts match");
        }
    }

    public int countEmailsAt(String domain)
    {
        int count = 0;
        for(Contact contact : contacts) {
            if(contact.getEmail().endsWith("@" + domain)) {
                count++;
            }
        }
        return count;
    }
}

